package dev.zomboid.hordes;import java.util.*;public class BudgetChecks49{
 static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}public static class Level{public boolean isClientSide(){return false;}}public static class Zombie{UUID id=UUID.randomUUID();Level l;boolean combat;Zombie(Level l){this.l=l;}public Level level(){return l;}public UUID getUUID(){return id;}public boolean isPassenger(){return false;}public boolean isVehicle(){return false;}}
 public static class Event{Zombie z;boolean loaded,canceled;Event(Zombie z){this.z=z;}public Object getEntity(){return z;}public Level getLevel(){return z.l;}public boolean loadedFromDisk(){return loaded;}public void setCanceled(boolean b){canceled=b;}}
 public static void main(String[]a){Map<String,Double>d=new HashMap<>(),min=new HashMap<>(),max=new HashMap<>(),v=WorldTuning.v;AmbientSettings47.install(d,min,max,v);ok(v.get(Budget49.KEY)==100&&min.get(Budget49.KEY)==1&&max.get(Budget49.KEY)==500,"actual native install exposes configurable default 100");try{AmbientSettings47.validate(Budget49.KEY,100.5);throw new AssertionError("fraction accepted");}catch(IllegalArgumentException expected){n++;}Level l=new Level(),other=new Level();var s=(ZoneReserve.State)ZoneReserve.state(l);var s2=(ZoneReserve.State)ZoneReserve.state(other);for(int i=0;i<99;i++)s.active.put(i,i);ok(Budget49.room(s,true),"one slot available at 99");s2.active.put(999,999);ok(!Budget49.room(s,true)&&Budget49.count()==100,"global budget includes other dimensions");Event join=new Event(new Zombie(l));ok(!Budget49.join(join)&&join.canceled,"all new zombie sources blocked at cap");join.loaded=true;join.canceled=false;ok(Budget49.join(join)&&!join.canceled,"saved zombies retained for safe reserve handling");Zombie z=new Zombie(l);s.active.put(z.id,z);Event pre=new Event(z);z.combat=true;ok(!Budget49.pre(pre)&&s.active.containsKey(z.id),"combat zombie never disappears when reducing cap");z.combat=false;ok(Budget49.pre(pre)&&pre.canceled&&!s.active.containsKey(z.id),"idle excess moves to existing reserve queue");v.put(Budget49.KEY,120d);ok(Budget49.room(s,true),"edited value changes admission immediately");ok(!Budget49.room(s,false),"zone limit still respected");String[]keys=Budget49.keys(new String[]{"a"}),labels=Budget49.labels(new String[]{"x"}),icons=Budget49.icons(new String[]{"y"});ok(keys.length==2&&keys[1].equals(Budget49.KEY)&&labels.length==keys.length&&icons.length==keys.length,"slider key label and icon arrays stay aligned");System.out.println("GLOBAL_BUDGET_NATIVE_SETTINGS_RESERVE_COMBAT_PANEL_CHECKS="+n);}}
